const expected = $env.N8N_WEBHOOK_SECRET || '';
const provided = $json.headers?.['x-staffmatch-webhook-secret'] || '';
if (!expected) throw new Error('N8N_WEBHOOK_SECRET is not configured');
if (provided !== expected) throw new Error('Unauthorized webhook request');
const body = $json.body || {};
if (!body.recipientEmail || !body.title || !body.message) throw new Error('Invalid notification payload');
const escapeHtml = (value) => String(value ?? '').replace(/[&<>'\"]/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','\"':'&quot;'}[character]));
return [{ json: {
  recipientEmail: body.recipientEmail,
  subject: `[Smart Hiring] ${body.title}`,
  html: `<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;color:#1f2937"><h2 style="color:#f97316">${escapeHtml(body.title)}</h2><p>Hello ${escapeHtml(body.recipientName || 'there')},</p><p>${escapeHtml(body.message)}</p><p><a href="${escapeHtml(body.actionUrl)}" style="display:inline-block;background:#f97316;color:white;padding:12px 18px;border-radius:10px;text-decoration:none">Open Smart Hiring</a></p><p style="font-size:12px;color:#6b7280">This automated message contains no chat text, issue description, or password information.</p></div>`,
  eventId: body.eventId
} }];
